class Solution {
    public long pickGifts(int[] gifts,int k){
        PriorityQueue<Integer> heap=new PriorityQueue<>(Comparator.reverseOrder());
        for(int gift:gifts)heap.offer(gift);
        while(k-->0)heap.offer((int)Math.sqrt(heap.poll()));
        long answer=0;
        for(int gift:heap)answer+=gift;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun pickGifts(gifts:IntArray,kValue:Int):Long{
        val heap=java.util.PriorityQueue<Int>(reverseOrder());
        for(gift in gifts)heap.offer(gift);
        var k=kValue;
        while(k-->0)heap.offer(kotlin.math.sqrt(heap.poll().toDouble()).toInt());
        return heap.sumOf{
            it.toLong()
        }
    }
}

code.cpp:
class Solution {
    public:long long pickGifts(vector<int>& gifts,int k){
        priority_queue<int> heap(gifts.begin(),gifts.end());
        while(k--){
            int gift=heap.top();
            heap.pop();
            heap.push(sqrt(gift));
        }
        long long answer=0;
        while(!heap.empty()){
            answer+=heap.top();
            heap.pop();
        }
        return answer;
    }
};
